// components/ScriptReader.js

import React, { useState, useCallback } from 'react';
import { FileText, UploadCloud } from 'lucide-react';

const ScriptReader = () => {
  const [fileUrl, setFileUrl] = useState('');
  const [fileName, setFileName] = useState('');

  const handleFileUpload = useCallback((event) => {
    const file = event.target.files[0];

    if (file) {
      setFileName(file.name);
      // Create a temporary URL for the local file
      const url = URL.createObjectURL(file);
      setFileUrl(url);

      // Revoke the object URL when the component unmounts or the file changes
      return () => {
        URL.revokeObjectURL(url);
      };
    }
  }, [setFileUrl, setFileName]);

  return (
    <div className="p-6 max-w-4xl mx-auto text-white">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-2xl font-bold flex items-center gap-2">
          <FileText className="w-6 h-6 text-accent" />
          Script Viewer
        </h2>
        <label className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 bg-primary rounded hover:bg-primaryDark transition">
          <UploadCloud className="w-5 h-5" />
          Upload Script
          <input
            type="file"
            accept=".doc,.docx"
            onChange={handleFileUpload}
            className="hidden" // Hide the default file input
          />
        </label>
      </div>
      <div className="bg-secondaryLight p-4 rounded shadow max-h-[70vh] overflow-y-auto">
        {fileUrl ? (
          <iframe
            src={`https://docs.google.com/viewer?url=${encodeURIComponent(fileUrl)}&embedded=true`}
            width="100%"
            height="100%"
            frameBorder="0"
            title="Document Viewer"
          ></iframe>
        ) : (
          <p className="text-midGray italic">Upload a `.doc` or `.docx` file to view it here.</p>
        )}
      </div>
      {fileName && <p className="text-midGray mt-2 text-sm italic">Viewing: {fileName}</p>}
    </div>
  );
};

export default ScriptReader;
